 /** Does `version` (MAJOR.MINOR.PATCH) satisfy `range`? See README.md for the range syntax. */
 export function satisfies(version: string, range: string): boolean {
-  throw new Error("not implemented");
+  const parsedVersion = parseVersion(version);
+  const parsedRange = parseRange(range);
+  return parsedRange.some((set) => set.every((comparator) => testComparator(parsedVersion, comparator)));
 }

 /** The highest of `versions` that satisfies `range`, or null when none does. See README.md. */
 export function maxSatisfying(versions: string[], range: string): string | null {
-  throw new Error("not implemented");
-}
+  const parsedRange = parseRange(range);
+  let best: Version | null = null;
+  let bestRaw: string | null = null;
+
+  for (const rawVersion of versions) {
+    const parsedVersion = parseVersion(rawVersion);
+    const matches = parsedRange.some((set) => set.every((comparator) => testComparator(parsedVersion, comparator)));
+    if (!matches) {
+      continue;
+    }
+    if (best === null || compareVersions(parsedVersion, best) > 0) {
+      best = parsedVersion;
+      bestRaw = rawVersion;
+    }
+  }
+
+  return bestRaw;
+}
+
+type Version = [number, number, number];
+
+type Comparator =
+  | { kind: "any" }
+  | { kind: "lt"; version: Version }
+  | { kind: "lte"; version: Version }
+  | { kind: "gt"; version: Version }
+  | { kind: "gte"; version: Version }
+  | { kind: "eq"; version: Version }
